-- Run as application user VIEW_DEMO (schema = VIEW_DEMO).
-- Quoted lowercase column names match SQL generated by weaver-view (e.g. "dep_key"); unquoted Oracle names fold to uppercase and break those queries.

DROP TABLE sys_user CASCADE CONSTRAINTS;
DROP TABLE position CASCADE CONSTRAINTS;
DROP TABLE department CASCADE CONSTRAINTS;
DROP TABLE sys_dict_data CASCADE CONSTRAINTS;
DROP TABLE test_field CASCADE CONSTRAINTS;

CREATE TABLE test_field
(
    id                   NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dept_id              NUMBER(19)      NULL,
    user_id              NUMBER(19)      NULL,
    status               VARCHAR2(100)   DEFAULT '0',
    del_flag             NUMBER(10)      DEFAULT 0,
    create_time          TIMESTAMP       NULL,
    create_by            VARCHAR2(64)    NULL,
    update_time          TIMESTAMP       NULL,
    update_by            VARCHAR2(64)    NULL,
    remark               VARCHAR2(500)   NULL
);

CREATE TABLE sys_dict_data
(
    dict_code   NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dict_sort   NUMBER(10)     DEFAULT 0,
    dict_label  VARCHAR2(100)  DEFAULT '',
    dict_value  VARCHAR2(100)  DEFAULT '',
    dict_type   VARCHAR2(100)  DEFAULT '',
    css_class   VARCHAR2(100)  NULL,
    list_class  VARCHAR2(100)  NULL,
    is_default  CHAR(1)        DEFAULT 'N',
    status      CHAR(1)        DEFAULT '0',
    create_by   VARCHAR2(64)   DEFAULT '',
    create_time TIMESTAMP      NULL,
    update_by   VARCHAR2(64)   DEFAULT '',
    update_time TIMESTAMP      NULL,
    remark      VARCHAR2(500)  NULL
);

CREATE TABLE department
(
    domain_key   VARCHAR2(100) NOT NULL,
    dep_key      VARCHAR2(100) NOT NULL,
    dep_name     VARCHAR2(100) NOT NULL,
    member_count NUMBER(10)    NULL,
    stopped      NUMBER(1)     NULL,
    create_time  TIMESTAMP     NOT NULL,
    create_user  VARCHAR2(100) NOT NULL,
    update_time  TIMESTAMP     NOT NULL,
    update_user  VARCHAR2(100) NOT NULL,
    PRIMARY KEY (domain_key, dep_key)
);

