CREATE TABLE position
(
    domain_key   VARCHAR2(100) NOT NULL,
    dep_key      VARCHAR2(100) NOT NULL,
    pos_key      VARCHAR2(100) NOT NULL,
    pos_name     VARCHAR2(100) NULL,
    create_time  TIMESTAMP     NOT NULL,
    create_user  VARCHAR2(100) NOT NULL,
    update_time  TIMESTAMP     NOT NULL,
    update_user  VARCHAR2(100) NOT NULL,
    PRIMARY KEY (domain_key, dep_key, pos_key)
);

