CREATE TABLE sys_user
(
    domain_key    VARCHAR2(100) NOT NULL,
    user_key      VARCHAR2(100) NOT NULL,
    parent_user   VARCHAR2(100) NULL,
    user_name     VARCHAR2(100) NOT NULL,
    position_id   VARCHAR2(100) NOT NULL,
    department_id VARCHAR2(100) NOT NULL,
    status        VARCHAR2(10)  NULL,
    photo         VARCHAR2(100) NULL,
    remark        VARCHAR2(1000) NULL,
    create_time   TIMESTAMP     NOT NULL,
    create_user   VARCHAR2(100) NOT NULL,
    update_time   TIMESTAMP     NOT NULL,
    update_user   VARCHAR2(100) NOT NULL,
    PRIMARY KEY (user_key)
);

